// Mock backend data for MSW, in the unchanged backend contract
// (web/src/lib/contract.ts): one pixel box per article at 300 DPI on the
// (196) page, plus type/title/kicker/bodyText/photoUrl.
//
// `replica` is the real 8 August 2026 issue ("(196) Capital Kranti_08
// august.pdf"), all 4 pages, generated by scripts/replica/extract_source.py:
// every box is the exact extent of a real article on that page, the text is
// the real text decoded from the paper's legacy Bharati font
// (scripts/replica/bharati_decode.py), and photos/ads are the real ones as
// printed. It's the acceptance test for the frontend: feed it through the
// pipeline and the result should look like the source paper. Regenerate it
// with `python3 scripts/replica/extract_source.py`, never by hand.
//
// `stress` is synthetic on purpose: boxes and text lengths a real day might
// throw at the layout engine (off-grid widths, a photo in a one-column box,
// far too much and far too little text, 6 pages) -- to prove the layout is
// fluid beyond the one issue it was measured against.

import type { ArticlePlacement, IssueResponse } from "@/lib/contract";
import replicaJson from "./replica/issue-2026-08-08.json";

const REPLICA = replicaJson as IssueResponse;

function firstPages(issue: IssueResponse, pages: number): IssueResponse {
  return { ...issue, pages, articles: issue.articles.filter((a) => a.page <= pages) };
}

// ---- stress fixture ----
const PX = 300 / 72; // pt -> px, the contract's DPI
const COL = 136.084; // grid pitch, pt
const LEFT = 15.5; // left margin, pt

const byId = (id: string) => REPLICA.articles.find((a) => a.id === id)!;
const longText = [byId("tushar-patel-award"), byId("mp-tourism"), byId("mena-atm")]
  .map((a) => a.bodyText)
  .join("\n\n");

function box(page: number, id: string, x0pt: number, y0pt: number, x1pt: number, y1pt: number,
             from: ArticlePlacement, over: Partial<ArticlePlacement> = {}): ArticlePlacement {
  return {
    ...from,
    ...over,
    id,
    page,
    x: Math.round(x0pt * PX),
    y: Math.round(y0pt * PX),
    width: Math.round((x1pt - x0pt) * PX),
    height: Math.round((y1pt - y0pt) * PX),
  };
}

function stressPage(page: number): ArticlePlacement[] {
  const top = page === 1 ? 272 : 46;
  const bottom = page === 6 ? 1452 : 1470;
  const mid = Math.round((top + bottom) / 2);
  return [
    // off-grid width (2.6 columns), text far too long for it -> must flag overflow, not drop text
    box(page, `p${page}-overflow`, LEFT, top, LEFT + COL * 2.6, mid, byId("teachers-portal"), { bodyText: longText }),
    // one-column box with a photo
    box(page, `p${page}-narrow-photo`, LEFT + COL * 2.6 + 12, top, LEFT + COL * 3.6 + 12, mid, byId("handloom")),
    // wide box with very little text -> must flag underflow
    box(page, `p${page}-underflow`, LEFT + COL * 3.6 + 24, top, 1092, mid, byId("bharuch-sog"),
        { bodyText: "ટૂંકા સમાચાર." }),
    // full-width lead with a photo and real text
    box(page, `p${page}-lead`, LEFT, mid + 10, 1092, bottom - 250, byId("mena-atm")),
    // a real ad creative squeezed into a different shape
    box(page, `p${page}-ad`, LEFT, bottom - 240, 700, bottom, byId("ad-chardham")),
    // title-less photo feature
    box(page, `p${page}-photo-feature`, 712, bottom - 240, 1092, bottom, byId("tiranga-gandhinagar")),
  ];
}

const STRESS: IssueResponse = {
  issueDate: "2026-08-09",
  issueNumber: 197,
  pages: 6,
  articles: [1, 2, 3, 4, 5, 6].flatMap(stressPage),
};

export const FIXTURES = {
  replica: REPLICA,
  onePage: firstPages(REPLICA, 1),
  twoPage: firstPages(REPLICA, 2),
  stress: STRESS,
} as const;

/** Which fixture the mock server returns for /api/issue -- override via the
 * MOCK_FIXTURE env var (replica | one | two | stress). Defaults to the full
 * 4-page replica of the real source paper. */
export function selectFixture(): IssueResponse {
  const key = process.env.MOCK_FIXTURE?.trim().toLowerCase();
  if (key === "one") return FIXTURES.onePage;
  if (key === "two") return FIXTURES.twoPage;
  if (key === "stress") return FIXTURES.stress;
  return FIXTURES.replica;
}
